CREATE TABLE proj25_accounts (account_id INTEGER PRIMARY KEY, account_label TEXT NOT NULL, balance_cents INTEGER NOT NULL CHECK (balance_cents >= 0));
CREATE TABLE proj25_ledger (entry_id INTEGER PRIMARY KEY, account_id INTEGER NOT NULL, transaction_ref TEXT NOT NULL, entry_type TEXT NOT NULL, amount_cents INTEGER NOT NULL, created_at TEXT NOT NULL);
INSERT INTO proj25_accounts VALUES (1, 'Asha', 10000), (2, 'Bilal', 5000);
INSERT INTO proj25_ledger VALUES (1, 1, 'OPEN-1', 'opening', 10000, '2026-11-22T09:00:00Z'), (2, 2, 'OPEN-2', 'opening', 5000, '2026-11-22T09:00:00Z');
SELECT a.account_id, a.balance_cents, SUM(l.amount_cents) AS ledger_balance FROM proj25_accounts a JOIN proj25_ledger l ON l.account_id=a.account_id GROUP BY a.account_id, a.balance_cents;

